import{_ as d}from"./chunks/9d335e252cac10e7e6ee4a1fc4b169a8.Ctv1r18z.js";import{_ as e,c as a,a2 as r,o}from"./chunks/framework.Bzjhwp8w.js";const g=JSON.parse('{"title":"Langflow中的嵌入模型","description":"Langflow中的嵌入模型","frontmatter":{"title":"Langflow中的嵌入模型","description":"Langflow中的嵌入模型","layout":"doc"},"headers":[],"relativePath":"langflow/components-embedding-models.md","filePath":"langflow/components-embedding-models.md"}'),n={name:"langflow/components-embedding-models.md"};function i(h,t,l,s,b,u){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="langflow中的嵌入模型" tabindex="-1">Langflow中的嵌入模型 <a class="header-anchor" href="#langflow中的嵌入模型" aria-label="Permalink to &quot;Langflow中的嵌入模型&quot;">​</a></h1><p>嵌入模型将文本转换为数值向量。这些嵌入捕获了输入文本的语义含义，并允许大型语言模型（LLMs）理解上下文。</p><p>请参考您特定组件的文档，以获取更多关于参数的信息。</p><h2 id="在流程中使用嵌入模型组件" tabindex="-1">在流程中使用嵌入模型组件 <a class="header-anchor" href="#在流程中使用嵌入模型组件" aria-label="Permalink to &quot;在流程中使用嵌入模型组件&quot;">​</a></h2><p>在这个文档摄取管道的示例中，<strong>OpenAI</strong> 嵌入模型被连接到一个向量数据库。该组件将文本块转换为向量，并存储在向量数据库中。这些向量化的数据可以用于提供聊天机器人、相似性搜索和代理等人工智能工作负载的信息。</p><p>此嵌入组件使用 OpenAI API 密钥进行认证。有关认证的更多信息，请参阅您特定嵌入组件的文档。</p><p><img src="'+d+'" alt="URL component in a data ingestion pipeline"></p><h2 id="ai-ml" tabindex="-1">AI/ML <a class="header-anchor" href="#ai-ml" aria-label="Permalink to &quot;AI/ML&quot;">​</a></h2><p>该组件使用 <a href="https://docs.aimlapi.com/api-overview/embeddings" target="_blank" rel="noreferrer">AI/ML API</a> 生成嵌入向量。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model_name</td><td>String</td><td>使用的人工智能/机器学习嵌入模型的名称</td></tr><tr><td>aiml_api_key</td><td>SecretString</td><td>用于认证人工智能/机器学习服务的 API 密钥</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>AIMLEmbeddingsImpl 的一个实例，用于生成 embeddings（嵌入向量）</td></tr></tbody></table><h2 id="amazon-bedrock-embeddings" tabindex="-1">Amazon Bedrock Embeddings <a class="header-anchor" href="#amazon-bedrock-embeddings" aria-label="Permalink to &quot;Amazon Bedrock Embeddings&quot;">​</a></h2><p>此组件用于从 <a href="https://aws.amazon.com/bedrock/" target="_blank" rel="noreferrer">Amazon Bedrock</a> 加载嵌入模型。</p><h3 id="输入参数" tabindex="-1">输入参数 <a class="header-anchor" href="#输入参数" aria-label="Permalink to &quot;输入参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>credentials_profile_name</td><td>String</td><td>在 <code>~/.aws/credentials</code> 或 <code>~/.aws/config</code> 中的 AWS 凭证配置文件名称，包含访问密钥或角色信息</td></tr><tr><td>model_id</td><td>String</td><td>要调用的模型的 ID，例如，<code>amazon.titan-embed-text-v1</code>。这相当于 <code>list-foundation-models</code> API 中的 <code>modelId</code> 属性</td></tr><tr><td>endpoint_url</td><td>String</td><td>用于设置特定服务端点的 URL，以替代默认 AWS 端点</td></tr><tr><td>region_name</td><td>String</td><td>要使用的 AWS 区域，例如，<code>us-west-2</code>。如果未提供，将回退到 <code>AWS_DEFAULT_REGION</code> 环境变量或 <code>~/.aws/config</code> 中指定的区域</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 Amazon Bedrock 生成嵌入的实例</td></tr></tbody></table><h2 id="astra-db-向量化" tabindex="-1">Astra DB 向量化 <a class="header-anchor" href="#astra-db-向量化" aria-label="Permalink to &quot;Astra DB 向量化&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>重要提示</strong> 此组件自 Langflow 版本 1.1.2 已被弃用。请改用 <a href="/dllm/components-vector-stores.html#astra-db-vector-store">Astra DB 向量存储组件</a>。</p></div><p>将此组件连接至 <a href="/dllm/components-vector-stores.html#astra-db-vector-store">Astra DB 向量存储组件</a>的<strong>Embeddings</strong>端口以生成嵌入。</p><p>此组件要求您的 Astra DB 数据库中有使用向量化嵌入提供程序集成的集合。有关更多信息和使用说明，请参阅 <a href="https://docs.datastax.com/en/astra-db-serverless/databases/embedding-generation.html" target="_blank" rel="noreferrer">Embedding Generation</a>。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>provider</td><td>嵌入提供者</td><td>使用的嵌入提供者</td></tr><tr><td>model_name</td><td>模型名称</td><td>使用的嵌入模型</td></tr><tr><td>authentication</td><td>认证</td><td>在 Astra 中存储您的 <a href="https://docs.datastax.com/en/astra-db-serverless/databases/embedding-generation.html#embedding-provider-authentication" target="_blank" rel="noreferrer">向量化嵌入提供者凭证</a> 的 API 密钥名称。（如果使用 <a href="https://docs.datastax.com/en/astra-db-serverless/databases/embedding-generation.html#supported-embedding-providers" target="_blank" rel="noreferrer">Astra 托管的嵌入提供者</a> 则不需要。）</td></tr><tr><td>provider_api_key</td><td>提供者 API 密钥</td><td>作为 <code>authentication</code> 的替代方案，直接提供您的嵌入提供者凭证。</td></tr><tr><td>model_parameters</td><td>模型参数</td><td>附加的模型参数</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 Astra vectorize 生成嵌入的实例</td></tr></tbody></table><h2 id="azure-openai-embeddings" tabindex="-1">Azure OpenAI Embeddings <a class="header-anchor" href="#azure-openai-embeddings" aria-label="Permalink to &quot;Azure OpenAI Embeddings&quot;">​</a></h2><p>此组件使用 Azure OpenAI 模型生成嵌入（embeddings）。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>Model</td><td>String</td><td>要使用的模型名称（默认：<code>text-embedding-3-small</code>）</td></tr><tr><td>Azure Endpoint</td><td>String</td><td>你的 Azure 端点，包括资源。例如：<code>https://example-resource.azure.openai.com/</code></td></tr><tr><td>Deployment Name</td><td>String</td><td>部署的名称</td></tr><tr><td>API Version</td><td>String</td><td>要使用的 API 版本，可选项包括不同日期</td></tr><tr><td>API Key</td><td>String</td><td>访问 Azure OpenAI 服务的 API 密钥</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 Azure OpenAI 生成嵌入的一个实例</td></tr></tbody></table><h2 id="cloudflare-workers-ai-embeddings" tabindex="-1">Cloudflare Workers AI Embeddings <a class="header-anchor" href="#cloudflare-workers-ai-embeddings" aria-label="Permalink to &quot;Cloudflare Workers AI Embeddings&quot;">​</a></h2><p>该组件使用 <a href="https://developers.cloudflare.com/workers-ai/" target="_blank" rel="noreferrer">Cloudflare Workers AI 模型</a> 生成向量嵌入。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>account_id</td><td>Cloudflare账号ID</td><td><a href="https://developers.cloudflare.com/fundamentals/setup/find-account-and-zone-ids/#find-account-id-workers-and-pages" target="_blank" rel="noreferrer">查找您的Cloudflare账号ID</a></td></tr><tr><td>api_token</td><td>Cloudflare API令牌</td><td><a href="https://developers.cloudflare.com/fundamentals/api/get-started/create-token/" target="_blank" rel="noreferrer">创建一个API令牌</a></td></tr><tr><td>model_name</td><td>模型名称</td><td><a href="https://developers.cloudflare.com/workers-ai/models/#text-embeddings" target="_blank" rel="noreferrer">支持的模型列表</a></td></tr><tr><td>strip_new_lines</td><td>去除换行符</td><td>是否从输入文本中去除换行符</td></tr><tr><td>batch_size</td><td>批处理大小</td><td>每批要嵌入的文本数</td></tr><tr><td>api_base_url</td><td>Cloudflare API基础URL</td><td>Cloudflare API的基础URL</td></tr><tr><td>headers</td><td>请求头</td><td>额外的请求头信息</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>一个用于通过 Cloudflare Workers 生成嵌入（embeddings）的实例</td></tr></tbody></table><h2 id="cohere-嵌入" tabindex="-1">Cohere 嵌入 <a class="header-anchor" href="#cohere-嵌入" aria-label="Permalink to &quot;Cohere 嵌入&quot;">​</a></h2><p>此组件用于从 <a href="https://cohere.com/" target="_blank" rel="noreferrer">Cohere</a> 加载嵌入模型。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>cohere_api_key</td><td>String</td><td>需要用于验证Cohere服务的API密钥</td></tr><tr><td>model</td><td>String</td><td>用于嵌入文本文档和执行查询的语言模型（默认：<code>embed-english-v2.0</code>）</td></tr><tr><td>truncate</td><td>Boolean</td><td>是否截断输入文本以适应模型的约束（默认：<code>False</code>）</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 Cohere 生成嵌入的实例</td></tr></tbody></table><h2 id="嵌入相似性" tabindex="-1">嵌入相似性 <a class="header-anchor" href="#嵌入相似性" aria-label="Permalink to &quot;嵌入相似性&quot;">​</a></h2><p>该组件用于计算两个嵌入向量之间选定形式的相似性。</p><h3 id="输入-2" tabindex="-1">输入 <a class="header-anchor" href="#输入-2" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>embedding_vectors</td><td>Embedding Vectors</td><td>包含正好两个数据对象的列表，内含要比较的嵌入向量。</td></tr><tr><td>similarity_metric</td><td>Similarity Metric</td><td>选择要使用的相似性度量。选项有：&quot;Cosine Similarity&quot;（余弦相似度）、&quot;Euclidean Distance&quot;（欧几里德距离）、&quot;Manhattan Distance&quot;（曼哈顿距离）。</td></tr></tbody></table><h3 id="outputs-3" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-3" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>similarity_data</td><td>Similarity Data</td><td>Data object 包含计算出的相似度评分和附加信息。</td></tr></tbody></table><h2 id="google-生成式-ai-嵌入" tabindex="-1">Google 生成式 AI 嵌入 <a class="header-anchor" href="#google-生成式-ai-嵌入" aria-label="Permalink to &quot;Google 生成式 AI 嵌入&quot;">​</a></h2><p>该组件使用来自 <code>langchain-google-genai</code> 包的 <code>GoogleGenerativeAIEmbeddings</code> 类连接到 Google 的生成式 AI 嵌入服务。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>api_key</td><td>API Key</td><td>访问 Google 的生成式 AI 服务的密钥（必需）</td></tr><tr><td>model_name</td><td>Model Name</td><td>要使用的嵌入模型的名称（默认：&quot;models/text-embedding-004&quot;）</td></tr></tbody></table><h3 id="outputs-4" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-4" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>构建的 GoogleGenerativeAIEmbeddings 对象</td></tr></tbody></table><h2 id="hugging-face-嵌入" tabindex="-1">Hugging Face 嵌入 <a class="header-anchor" href="#hugging-face-嵌入" aria-label="Permalink to &quot;Hugging Face 嵌入&quot;">​</a></h2><p>:::note 此组件在 Langflow 版本 1.0.18 中已被弃用。请改用 <a href="#hugging-face-embeddings-inference-api">Hugging Face API 嵌入组件</a>。 :::</p><p>该组件用于从 HuggingFace 加载嵌入模型。</p><p>使用此组件，可以利用本地下载的 Hugging Face 模型生成嵌入。请确保您有足够的计算资源来运行这些模型。</p><h3 id="输入-3" tabindex="-1">输入 <a class="header-anchor" href="#输入-3" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>Cache Folder</td><td>Cache Folder</td><td>HuggingFace 模型缓存的文件夹路径</td></tr><tr><td>Encode Kwargs</td><td>Encoding Arguments</td><td>编码过程的附加参数</td></tr><tr><td>Model Kwargs</td><td>Model Arguments</td><td>模型的附加参数</td></tr><tr><td>Model Name</td><td>Model Name</td><td>使用的 HuggingFace 模型的名称</td></tr><tr><td>Multi Process</td><td>Multi-Process</td><td>是否使用多进程</td></tr></tbody></table><h3 id="输出-3" tabindex="-1">输出 <a class="header-anchor" href="#输出-3" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>生成的嵌入向量信息</td></tr></tbody></table><h2 id="hugging-face-embeddings-推理api" tabindex="-1">Hugging Face embeddings 推理API <a class="header-anchor" href="#hugging-face-embeddings-推理api" aria-label="Permalink to &quot;Hugging Face embeddings 推理API&quot;">​</a></h2><p>此组件使用 <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face 推理API模型</a> 生成嵌入（embeddings）。</p><p>使用此组件可以通过 Hugging Face 的托管模型创建嵌入。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>API Key</td><td>API Key</td><td>用于访问 Hugging Face Inference API 的 API 密钥</td></tr><tr><td>API URL</td><td>API URL</td><td>Hugging Face Inference API 的 URL</td></tr><tr><td>Model Name</td><td>Model Name</td><td>用于嵌入的模型名称</td></tr><tr><td>Cache Folder</td><td>Cache Folder</td><td>缓存 Hugging Face 模型的文件夹路径</td></tr><tr><td>Encode Kwargs</td><td>Encoding Arguments</td><td>编码过程的额外参数</td></tr><tr><td>Model Kwargs</td><td>Model Arguments</td><td>模型的额外参数</td></tr><tr><td>Multi Process</td><td>Multi-Process</td><td>是否使用多进程</td></tr></tbody></table><h3 id="outputs-5" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-5" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>生成的embeddings（嵌入）</td></tr></tbody></table><h2 id="lm-studio-嵌入" tabindex="-1">LM Studio 嵌入 <a class="header-anchor" href="#lm-studio-嵌入" aria-label="Permalink to &quot;LM Studio 嵌入&quot;">​</a></h2><p>该组件使用 <a href="https://lmstudio.ai/docs" target="_blank" rel="noreferrer">LM Studio</a> 模型生成嵌入。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>model</td><td>Model</td><td>用于生成嵌入的 LM Studio 模型</td></tr><tr><td>base_url</td><td>LM Studio Base URL</td><td>LM Studio API 的基础 URL</td></tr><tr><td>api_key</td><td>LM Studio API Key</td><td>用于认证 LM Studio 的 API 密钥</td></tr><tr><td>temperature</td><td>Model Temperature</td><td>模型的温度设置</td></tr></tbody></table><h3 id="outputs-6" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-6" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>The generated embeddings</td></tr></tbody></table><h3 id="输出-4" tabindex="-1">输出 <a class="header-anchor" href="#输出-4" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>生成的embeddings（嵌入）</td></tr></tbody></table><h2 id="mistralai" tabindex="-1">MistralAI <a class="header-anchor" href="#mistralai" aria-label="Permalink to &quot;MistralAI&quot;">​</a></h2><p>此组件使用 <a href="https://docs.mistral.ai/" target="_blank" rel="noreferrer">MistralAI</a> 模型生成嵌入（embeddings）。</p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>model</td><td>String</td><td>使用的 MistralAI 模型（默认值：&quot;mistral-embed&quot;）</td></tr><tr><td>mistral_api_key</td><td>SecretString</td><td>用于与 MistralAI 认证的 API 密钥</td></tr><tr><td>max_concurrent_requests</td><td>Integer</td><td>最大并发 API 请求数（默认值：64）</td></tr><tr><td>max_retries</td><td>Integer</td><td>请求失败的最大重试次数（默认值：5）</td></tr><tr><td>timeout</td><td>Integer</td><td>请求超时时间（以秒为单位）（默认值：120）</td></tr><tr><td>endpoint</td><td>String</td><td>自定义 API 端点 URL（默认值：<code>https://api.mistral.ai/v1/</code>）</td></tr></tbody></table><h3 id="outputs-7" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-7" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>用于生成嵌入的 MistralAIEmbeddings 实例</td></tr></tbody></table><h2 id="nvidia" tabindex="-1">NVIDIA <a class="header-anchor" href="#nvidia" aria-label="Permalink to &quot;NVIDIA&quot;">​</a></h2><p>该组件使用 <a href="https://docs.nvidia.com" target="_blank" rel="noreferrer">NVIDIA 模型</a> 生成嵌入。</p><h3 id="inputs-7" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-7" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>model</td><td>String</td><td>要用于嵌入生成的 NVIDIA 模型（例如，<code>nvidia/nv-embed-v1</code>）</td></tr><tr><td>base_url</td><td>String</td><td>NVIDIA API 的基础 URL（默认值：<code>https://integrate.api.nvidia.com/v1</code>）</td></tr><tr><td>nvidia_api_key</td><td>SecretString</td><td>用于与 NVIDIA 服务进行验证的 API 密钥</td></tr><tr><td>temperature</td><td>Float</td><td>用于嵌入生成的模型温度（默认值：<code>0.1</code>）</td></tr></tbody></table><h3 id="输出-5" tabindex="-1">输出 <a class="header-anchor" href="#输出-5" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>生成嵌入的 NVIDIAEmbeddings 实例</td></tr></tbody></table><h2 id="ollama-embeddings" tabindex="-1">Ollama Embeddings <a class="header-anchor" href="#ollama-embeddings" aria-label="Permalink to &quot;Ollama Embeddings&quot;">​</a></h2><p>该组件使用 <a href="https://ollama.com/" target="_blank" rel="noreferrer">Ollama 模型</a> 生成嵌入。</p><h3 id="inputs-8" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-8" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>Ollama Model</td><td>String</td><td>要使用的 Ollama 模型名称（默认：<code>llama2</code>）</td></tr><tr><td>Ollama Base URL</td><td>String</td><td>Ollama API 的基础 URL（默认：<code>http://localhost:11434</code>）</td></tr><tr><td>Model Temperature</td><td>Float</td><td>模型的温度参数。用于调整生成嵌入中的随机性</td></tr></tbody></table><h3 id="outputs-8" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-8" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 Ollama 生成嵌入（embeddings）实例</td></tr></tbody></table><h2 id="openai-embeddings" tabindex="-1">OpenAI Embeddings <a class="header-anchor" href="#openai-embeddings" aria-label="Permalink to &quot;OpenAI Embeddings&quot;">​</a></h2><p>该组件用于从 <a href="https://openai.com/" target="_blank" rel="noreferrer">OpenAI</a> 加载嵌入模型。</p><h3 id="inputs-9" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-9" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>OpenAI API Key</td><td>String</td><td>用于访问OpenAI API的API密钥</td></tr><tr><td>Default Headers</td><td>Dict</td><td>HTTP请求的默认headers</td></tr><tr><td>Default Query</td><td>NestedDict</td><td>HTTP请求的默认查询参数</td></tr><tr><td>Allowed Special</td><td>List</td><td>允许处理的特殊token（默认：<code>[]</code>）</td></tr><tr><td>Disallowed Special</td><td>List</td><td>不允许处理的特殊token（默认：<code>[&quot;all&quot;]</code>）</td></tr><tr><td>Chunk Size</td><td>Integer</td><td>处理的分块大小（默认：<code>1000</code>）</td></tr><tr><td>Client</td><td>Any</td><td>用于发送请求的HTTP客户端</td></tr><tr><td>Deployment</td><td>String</td><td>模型的部署名称（默认：<code>text-embedding-3-small</code>）</td></tr><tr><td>Embedding Context Length</td><td>Integer</td><td>嵌入上下文的长度（默认：<code>8191</code>）</td></tr><tr><td>Max Retries</td><td>Integer</td><td>请求失败的最大重试次数（默认：<code>6</code>）</td></tr><tr><td>Model</td><td>String</td><td>使用的模型名称（默认：<code>text-embedding-3-small</code>）</td></tr><tr><td>Model Kwargs</td><td>NestedDict</td><td>模型的附加关键字参数</td></tr><tr><td>OpenAI API Base</td><td>String</td><td>OpenAI API的基本URL</td></tr><tr><td>OpenAI API Type</td><td>String</td><td>OpenAI API的类型</td></tr><tr><td>OpenAI API Version</td><td>String</td><td>OpenAI API的版本</td></tr><tr><td>OpenAI Organization</td><td>String</td><td>与API密钥关联的组织</td></tr><tr><td>OpenAI Proxy</td><td>String</td><td>请求的代理服务器</td></tr><tr><td>Request Timeout</td><td>Float</td><td>HTTP请求的超时时间</td></tr><tr><td>Show Progress Bar</td><td>Boolean</td><td>是否显示处理的进度条（默认：<code>False</code>）</td></tr><tr><td>Skip Empty</td><td>Boolean</td><td>是否跳过空输入（默认：<code>False</code>）</td></tr><tr><td>TikToken Enable</td><td>Boolean</td><td>是否启用TikToken（默认：<code>True</code>）</td></tr><tr><td>TikToken Model Name</td><td>String</td><td>TikToken模型名称</td></tr></tbody></table><h3 id="输出-6" tabindex="-1">输出 <a class="header-anchor" href="#输出-6" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>一个使用 OpenAI 生成嵌入（embeddings）的实例</td></tr></tbody></table><h2 id="text-embedder" tabindex="-1">Text embedder <a class="header-anchor" href="#text-embedder" aria-label="Permalink to &quot;Text embedder&quot;">​</a></h2><p>该组件利用指定的嵌入模型为给定的消息生成嵌入。</p><h3 id="inputs-10" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-10" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>embedding_model</td><td>Embedding Model</td><td>用于生成embedding的embedding模型。</td></tr><tr><td>message</td><td>Message</td><td>要为其生成embedding的消息。</td></tr></tbody></table><h3 id="outputs-9" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-9" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>embeddings</td><td>Embedding Data</td><td>包含原始文本及其嵌入向量的数据对象。</td></tr></tbody></table><h2 id="vertexai-embeddings" tabindex="-1">VertexAI Embeddings <a class="header-anchor" href="#vertexai-embeddings" aria-label="Permalink to &quot;VertexAI Embeddings&quot;">​</a></h2><p>该组件是 <a href="https://cloud.google.com/vertex-ai" target="_blank" rel="noreferrer">Google Vertex AI</a> <a href="https://cloud.google.com/vertex-ai/docs/generative-ai/embeddings/get-text-embeddings" target="_blank" rel="noreferrer">Embeddings API</a> 的一个封装。</p><h3 id="inputs-11" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-11" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>credentials</td><td>Credentials</td><td>默认的自定义凭据</td></tr><tr><td>location</td><td>String</td><td>发起 API 调用时使用的默认位置（默认为：<code>us-central1</code>）</td></tr><tr><td>max_output_tokens</td><td>Integer</td><td>令牌限制决定了一次提示输出的最大文本量（默认为：<code>128</code>）</td></tr><tr><td>model_name</td><td>String</td><td>Vertex AI 大型语言模型的名称（默认为：<code>text-bison</code>）</td></tr><tr><td>project</td><td>String</td><td>发起 Vertex API 调用时使用的默认 GCP 项目</td></tr><tr><td>request_parallelism</td><td>Integer</td><td>允许向 VertexAI 模型发出请求的并行数量（默认为：<code>5</code>）</td></tr><tr><td>temperature</td><td>Float</td><td>调整生成文本的随机性程度。应为非负值（默认为：<code>0</code>）</td></tr><tr><td>top_k</td><td>Integer</td><td>模型选择输出令牌的方式，下一个令牌从前 <code>k</code> 个令牌中选择（默认为：<code>40</code>）</td></tr><tr><td>top_p</td><td>Float</td><td>从最可能到最不可能的令牌中选择，直到它们概率的总和超过 <code>p</code> 值（默认为：<code>0.95</code>）</td></tr><tr><td>tuned_model_name</td><td>String</td><td>调整过的模型的名称。如果提供了此项，<code>model_name</code> 将被忽略</td></tr><tr><td>verbose</td><td>Boolean</td><td>此参数控制输出的详细程度。当设置为 <code>True</code> 时，它会打印链的内部状态以帮助调试（默认为：<code>False</code>）</td></tr></tbody></table><h3 id="outputs-10" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-10" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>embeddings</td><td>Embeddings</td><td>使用 VertexAI 生成嵌入（embeddings）的实例</td></tr></tbody></table>',116)]))}const p=e(n,[["render",i]]);export{g as __pageData,p as default};
